{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic is not encrypted with a Customer Supplied Encryption Key (CSEK), which may lead to data being encrypted with a Google-managed key that is not under the user's control."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n  kms_key_name = \"projects/your-project/locations/your-location/keyRings/your-keyring/cryptoKeys/your-key\"\n}",
  "fix_summary": "Added kms_key_name attribute to google_pubsub_topic to enable encryption with a Customer Supplied Encryption Key (CSEK)"
}
